 if(phase_==Phase::ColdClear||phase_==Phase::MainScratch){auto r=early_.advanceBefore(d,irq,available);if(r.returned)phase_=phase_==Phase::ColdClear?Phase::Cold:Phase::Main;return {r.clocks,false,Block::None};}
 if(phase_==Phase::Image){auto before=early_.imageTask()->stage();auto r=early_.advanceBefore(d,irq,available);if(before==ResetImageTask::Stage::PublishOverlay&&r.clocks)overlayPending_=true;if(r.returned){phase_=Phase::Cold;cold_.resume();}else if(early_.child()!=ResetImageTask::Child::None&&early_.child()!=ResetImageTask::Child::FirmwareUpdate){imageText_=early_.child();unsigned source=imageText_==ResetImageTask::Child::ErrorMessage?0xaab7:imageText_==ResetImageTask::Child::UpdateMessage?0xaaab:0xaa91;if(!lcd_.start(LcdTextTask::Kind::String,0,0,source))throw std::logic_error("K reset text admission");childOwner_=ChildOwner::ImageText;}return {r.clocks,false,Block::None};}
 auto arb=d.pendingIrqs?1u:0u;if(arb)(void)d.read8(0xfffff2);auto clocks=total-arb;auto begin=d.cycles;auto cr=credits(d);bool stack=false;
 if(phase_==Phase::Cold){auto stage=cold_.stage();stack=stage!=C::Stage::Main;check(cold_.advanceBefore(clocks,cr)==clocks);if(stage==C::Stage::Prefix)phase_=Phase::Prefix;else if(stage==C::Stage::Runtime)phase_=Phase::Runtime;else{phase_=Phase::MainScratch;check(early_.startLeaf(StartupTask::Kind::MainScratchClear));}}
 else if(phase_==Phase::Prefix){auto stage=prefix_.stage();stack=stage==P::Stage::RetainDelay||stage==P::Stage::RetainInner||prefixCall(stage);check(prefix_.advanceBefore(clocks,cr,[&]{d.cycles=begin+9;return d.read8(0xfffe3d);},[&](unsigned value){d.cycles=begin+9;d.write8(0xfffe3d,uint8_t(value));})==clocks);if(prefix_.complete()){phase_=Phase::Image;check(early_.startImage(prefix_.romCopy()?ResetImageTask::Entry::RomCopy:ResetImageTask::Entry::Verify));}else beginInternal();}
 else if(phase_==Phase::Runtime){auto stage=runtime_.stage();stack=stage!=R::Stage::Unmask&&stage!=R::Stage::Return;check(runtime_.advanceBefore(clocks,cr)==clocks);if(stage==R::Stage::Unmask)irq.setMask(ControllerInterruptRuntime::Mask::Enabled);if(runtime_.complete()){phase_=Phase::Cold;cold_.resume();}else beginInternal();}
